import type { HTMLAttributes, ReactNode, Ref } from "react";
import { FeaturedIcon } from "./FeaturedIcon";
import "./Alert.css";

export type AlertVariant = "neutral" | "info" | "success" | "warning" | "error";
export type AlertBoxVariant = "filled" | "outline";
export type AlertLive = "off" | "polite" | "assertive";

/** Announcement urgency → ARIA live-region role. */
const ROLE_FOR_LIVE = { assertive: "alert", polite: "status", off: undefined } as const;

/** Whether a ReactNode slot has content to render.
 *
 *  `{node && …}` renders `0` itself when node is `0`, leaving stray text in the DOM.
 *  Conversely, checking only `node != null` lets `""` or `[]` through and renders an **empty
 *  shell** (a contentless 40px plate, an empty text line). To prevent both failures, ask whether
 *  there is something to render, not merely whether it is non-null — so empty strings and empty
 *  arrays are treated as absent too.
 *
 *  **The same function is duplicated in `Toast.tsx`.** It is not exported and imported from here
 *  because of the distribution model — if Toast imports this file in the copy-paste registry,
 *  someone copying Toast must bring along Alert even though they do not use it. Until a shared
 *  utility module exists, five duplicated lines are better than the wrong dependency. **If you
 *  fix one, you must fix the other too.** */
const isPresent = (node: ReactNode): boolean => {
  if (node == null || node === false || node === "") return false;
  if (Array.isArray(node)) return node.some(isPresent);
  return true;
};

export interface AlertProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "className" | "title" | "role"> {
  /**
   * Visual variant. `neutral` is a note that carries no judgement and asks for no attention (a
   * promotion line, a device notice); the four others judge the content (`prop-usage-contract` § valence).
   *
   * @default "info"
   */
  variant?: AlertVariant;
  /**
   * How the box is drawn, the field-variant words (`component-vocabulary.md`). `filled` paints the
   * variant's status tint and colours the copy with it. `outline` draws the page's own surface and
   * ink inside a decorative edge, so ONLY the icon carries the variant's colour, as a Toast does:
   * for a notice that sits inside page content and must not outweigh it. `outline` relies on the
   * icon and the title to say which status it is, so give it both.
   *
   * @default "filled"
   */
  boxVariant?: AlertBoxVariant;
  /**
   * Announcement urgency. **Decoupled from the visual variant** — a red error does not necessarily
   * mean “interrupt what is being read.” Use `assertive` (role=alert) only when it must be announced
   * immediately; the default is `polite` (role=status). The case that earns it across this library is a **submit failure** — the user just acted and the attempt failed, which interrupts in a way an ambient notice does not. Caution: a region rendered from the start
   * is not guaranteed to be announced — the region must exist first and then have content inserted
   * or changed for a screen reader to read it, so `off` is the honest choice for a static banner.
   *
   * @default "polite"
   */
  live?: AlertLive;
  title?: ReactNode;
  icon?: ReactNode;
  /**
   * Controls that act on the notice (Buttons), drawn under the copy on the box line: the copy takes
   * the text inset, a pressable box does not (component-contract.md §6 rule 8).
   */
  actions?: ReactNode;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function Alert({
  variant = "info",
  boxVariant = "filled",
  live = "polite",
  title,
  icon,
  children,
  actions,
  className,
  ...props
}: AlertProps) {
  const hasTitle = isPresent(title);
  const hasDescription = isPresent(children);
  const hasActions = isPresent(actions);
  return (
    <div
      {...props}
      role={ROLE_FOR_LIVE[live]}
      data-variant={variant}
      data-box-variant={boxVariant}
      className={className ? `sd-alert ${className}` : "sd-alert"}
    >
      {/* The leading visual is a FeaturedIcon plate, the same treatment Dialog/Drawer use — it
          owns the geometry (padding from the surface scale, radius, glyph size) and sets no
          colour, so the glyph takes the variant colour the icon part relays. `raised` on the
          status tint, `sunken` on the plain surface of `outline` (FeaturedIcon's own rule). */}
      {isPresent(icon) && (
        <FeaturedIcon
          aria-hidden="true"
          size="large"
          tone={boxVariant === "outline" ? "sunken" : "raised"}
          className="sd-alert__icon"
        >
          {icon}
        </FeaturedIcon>
      )}
      {(hasTitle || hasDescription || hasActions) && (
        <div className="sd-alert__content">
          {hasTitle && <div className="sd-alert__title sd-type-subtitle-medium">{title}</div>}
          {hasDescription && (
            <div className="sd-alert__description sd-type-body-medium">{children}</div>
          )}
          {hasActions && <div className="sd-alert__actions">{actions}</div>}
        </div>
      )}
    </div>
  );
}

/* A row of [icon · content]. `gap` is the icon↔content distance only; the title↔
   description distance is the content column's own `content-gap`, so the two axes are tuned
   separately (a single `gap` on a grid forced them to share one value).

   `center` so the [plate · content] row reads as one band — the case worth optimising is the
   usual one- or two-line notice. The trade is a long body, where the plate drifts toward the
   middle of the description rather than sitting with the title; accepted deliberately, and
   Alert wears it better than Toast because it is wide and short, so it wraps less often.
   `Toast.css` makes the same call — the two are a sibling pair and must not diverge here. */
.sd-alert {
  display: flex;
  align-items: center;
  gap: var(--sd-alert-gap);
  /* One surface step on every side. The copy is held clear of the surface curve by the content
     column's own inline inset, not by the plate — because `icon` is optional and the text axis
     must remain stable whether or not the plate renders. */
  padding: var(--sd-alert-padding);
  border: var(--sd-alert-border-width) solid transparent;
  border-radius: var(--sd-alert-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-alert[data-variant="neutral"] {
  background: var(--sd-alert-background-neutral);
  color: var(--sd-alert-foreground-neutral);
  border-color: var(--sd-alert-border-neutral);
  --sd-alert-icon-color-current: var(--sd-alert-foreground-neutral);
  --sd-alert-description-color-current: var(--sd-alert-foreground-neutral);
}

.sd-alert[data-variant="info"] {
  background: var(--sd-alert-background-info);
  color: var(--sd-alert-foreground-info);
  border-color: var(--sd-alert-border-info);
  --sd-alert-icon-color-current: var(--sd-alert-foreground-info);
  --sd-alert-description-color-current: var(--sd-alert-foreground-info);
}

.sd-alert[data-variant="success"] {
  background: var(--sd-alert-background-success);
  color: var(--sd-alert-foreground-success);
  border-color: var(--sd-alert-border-success);
  --sd-alert-icon-color-current: var(--sd-alert-foreground-success);
  --sd-alert-description-color-current: var(--sd-alert-foreground-success);
}

.sd-alert[data-variant="warning"] {
  background: var(--sd-alert-background-warning);
  color: var(--sd-alert-foreground-warning);
  border-color: var(--sd-alert-border-warning);
  --sd-alert-icon-color-current: var(--sd-alert-foreground-warning);
  --sd-alert-description-color-current: var(--sd-alert-foreground-warning);
}

.sd-alert[data-variant="error"] {
  background: var(--sd-alert-background-error);
  color: var(--sd-alert-foreground-error);
  border-color: var(--sd-alert-border-error);
  --sd-alert-icon-color-current: var(--sd-alert-foreground-error);
  --sd-alert-description-color-current: var(--sd-alert-foreground-error);
}

/* boxVariant="outline": the page's own surface and ink inside a decorative edge, the status carried
   by the icon alone (the Toast anatomy, inline). Placed after the variant rules, which it overrides
   at equal specificity; the variant still sets the icon's colour through the relay below. */
.sd-alert[data-box-variant="outline"] {
  background: var(--sd-alert-background-outline);
  color: var(--sd-alert-foreground-outline);
  border-color: var(--sd-alert-border-outline);
  --sd-alert-description-color-current: var(--sd-alert-description-foreground-outline);
}

/* The variant's colour reaches the plate's glyph through a `-current` relay set on the root
   (component-contract.md §6.5), so `outline` can re-ink the copy without losing the icon's status.
   FeaturedIcon sets no colour of its own, so the glyph follows. */
.sd-alert__icon {
  color: var(--sd-alert-icon-color-current);
}

/* The description takes the variant colour on a status tint and steps back to the muted ink under
   its title on the plain `outline` surface, as a Toast's does; same relay. */
.sd-alert__description {
  color: var(--sd-alert-description-color-current);
}

/* The title and description are text the component draws on its own painted surface, so the
   column takes the text inset, plate or no plate (component-contract.md §6 rule 8, component-owned
   text). Inline only: `text-inset.block` is spent by no part. */
.sd-alert__content {
  display: flex;
  flex-direction: column;
  gap: var(--sd-alert-content-gap);
  flex: 1;
  min-width: 0;
}

/* The copy the alert draws on its own surface takes the text inset; the actions row under it holds
   pressable boxes, which stay on the box line (component-contract.md §6 rule 8). */
.sd-alert__title,
.sd-alert__description {
  padding-inline: var(--sd-alert-content-padding-inline);
}

/* The title carries no colour of its own: it inherits the root's foreground, the variant colour
   on a status tint, the page's ink on `outline`. */
